param([string]$GatePath,[string]$Python='python')
$ErrorActionPreference='Stop';$projectRoot=(Resolve-Path -LiteralPath (Join-Path $PSScriptRoot '..\..\..')).Path
$expected=[ordered]@{
 'paper_faithful/sst/__init__.py'='sst_init_py';'paper_faithful/sst/cache_manifest.py'='sst_cache_manifest_py';'paper_faithful/sst/cache_writer.py'='sst_cache_writer_py';'paper_faithful/sst/cohort_cache.py'='sst_cohort_cache_py';'paper_faithful/sst/storage.py'='sst_storage_py';'paper_faithful/sst/transform.py'='sst_transform_py';'paper_faithful/sst/windowing.py'='sst_windowing_py';'paper_faithful/training/__init__.py'='training_init_py';'paper_faithful/training/cache_loader.py'='training_cache_loader_py';'paper_faithful/training/cli.py'='cli_py';'paper_faithful/training/metrics.py'='training_metrics_py';'paper_faithful/training/models.py'='training_models_py';'paper_faithful/training/protocols.py'='training_protocols_py';'paper_faithful/training/run_manifest.py'='training_run_manifest_py';'paper_faithful/training/splits.py'='training_splits_py';'paper_faithful/training/storage.py'='training_storage_py';'paper_faithful/training/trainer.py'='trainer_py';'paper_faithful/training/verify_run.py'='verify_run_py'
}
$probe=(Resolve-Path -LiteralPath (Join-Path $PSScriptRoot 'r17_import_closure_probe.py')).Path;$old=$env:PYTHONDONTWRITEBYTECODE;try{$env:PYTHONDONTWRITEBYTECODE='1';$out=@(& $Python $probe);if($LASTEXITCODE-ne0){throw 'import probe failed'}}finally{if($null-eq$old){Remove-Item Env:PYTHONDONTWRITEBYTECODE -ErrorAction SilentlyContinue}else{$env:PYTHONDONTWRITEBYTECODE=$old}}
$discovered=@((($out-join"`n")|ConvertFrom-Json)|%{$_});$reachable=@($discovered|%{[string]$_.path}|Sort-Object -Unique);$expectedPaths=@($expected.Keys|Sort-Object -Unique);if(($reachable-join'|')-ne($expectedPaths-join'|')){throw 'reachable import closure changed'}
$bindings=@();foreach($path in $expected.Keys){$full=(Resolve-Path -LiteralPath (Join-Path $projectRoot $path.Replace('/','\'))).Path;$bindings+=@([ordered]@{name=$expected[$path];path=$full;sha256=(Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash.ToLowerInvariant()})}
$gateValidated=$false;if($GatePath){$gate=Get-Content -LiteralPath (Resolve-Path -LiteralPath $GatePath) -Raw|ConvertFrom-Json;$byName=@{};foreach($b in @($gate.source_bindings)){$byName[[string]$b.name]=$b};foreach($b in $bindings){if(!$byName.ContainsKey($b.name)-or[string]$byName[$b.name].content_type-ne'utf8_text'-or-not[IO.Path]::GetFullPath([string]$byName[$b.name].path).Equals($b.path,[StringComparison]::OrdinalIgnoreCase)-or[string]$byName[$b.name].sha256-ne$b.sha256){throw "gate import binding failed: $($b.name)"}};$gateValidated=$true}
[ordered]@{status='pass';reachable_repository_modules=$reachable.Count;bound_repository_modules=$bindings.Count;omission_refused=$true;gate_validated=$gateValidated;source_bindings=$bindings;pilot_launched=$false}|ConvertTo-Json -Depth 6 -Compress
